#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;

my $root = '/bench/repo';

sub read_file {
    open my $fh, '<', $_[0] or return '';
    local $/; my $c = <$fh>; close $fh; return $c // '';
}

my @all_go;
find(sub {
    return unless /\.go$/;
    push @all_go, $File::Find::name;
}, $root);

my @symbols;
for my $file (@all_go) {
    next unless $file =~ m{/internal/};
    next if $file =~ /_test\.go$/;
    my $content = read_file($file);
    my ($pkg) = $content =~ /^package\s+(\w+)/m or next;
    while ($content =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/mg) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        next if $name =~ /^(Test|Benchmark|Example|Fuzz)/;
        my $recv_type = '';
        if ($recv) { ($recv_type) = $recv =~ /(?:\*?\s*)?([\w.]+)\s*$/; }
        push @symbols, {
            pkg => $pkg, name => $name, path => $file,
            kind => ($recv ? 'method' : 'func'), recv_type => $recv_type,
        };
    }
}

my %contents;
for my $file (@all_go) { $contents{$file} = read_file($file); }

my %file_pkg;
for my $file (@all_go) {
    ($file_pkg{$file}) = $contents{$file} =~ /^package\s+(\w+)/m;
}

my %file_imports;
for my $file (@all_go) {
    my $c = $contents{$file};
    while ($c =~ /^import\s+"([^"]+)"/mg) {
        my $imp = $1; my $alias = (split m{/}, $imp)[-1];
        $file_imports{$file}{$alias} = 1;
    }
    while ($c =~ /^import\s+\(([\s\S]*?)\)/mg) {
        my $block = $1;
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $imp) = ($1, $2);
            $alias //= (split m{/}, $imp)[-1];
            $file_imports{$file}{$alias} = 1;
        }
    }
}

sub count_pat {
    my ($text, $re) = @_;
    my $n = 0; while ($text =~ /$re/g) { $n++ } return $n;
}

my @results;
for my $sym (@symbols) {
    my ($name, $pkg, $def_file) = @{$sym}{qw/name pkg path/};
    my $fanin = 0;

    if ($sym->{kind} eq 'func') {
        my $qpat = qr/\b\Q$pkg\E\.\Q$name\E\s*\(/;
        my $upat = qr/(?<![.\w])\Q$name\E\s*\(/;
        for my $file (@all_go) {
            my $text = $contents{$file};
            next unless length $text;
            my $same_pkg = defined $file_pkg{$file} && $file_pkg{$file} eq $pkg;
            my $imports = $file_imports{$file}{$pkg};
            if ($imports || $same_pkg) {
                $fanin += count_pat($text, $qpat);
                if ($same_pkg) {
                    my $u = count_pat($text, $upat);
                    $fanin += $u;
                    if ($file eq $def_file && $text =~ /^func\s+\Q$name\E\s*\(/m) {
                        $fanin-- if $u > 0;
                    }
                }
            } else {
                $fanin += count_pat($text, $qpat);
            }
        }
    } else {
        my $mpat = qr/\.\Q$name\E\s*\(/;
        for my $file (@all_go) {
            my $text = $contents{$file};
            my $c = count_pat($text, $mpat);
            $fanin += $c;
            if ($file eq $def_file && $text =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/m) {
                $fanin--;
            }
        }
    }
    push @results, { %$sym, fanin => $fanin };
}

@results = sort { $b->{fanin} <=> $a->{fanin} } @results;
print "TOP 40:\n";
for my $r (@results[0..39]) {
    my $sym = $r->{kind} eq 'method' ? "($r->{recv_type}).$r->{name}" : $r->{name};
    printf "%4d  %s  %s\n", $r->{fanin}, $sym, $r->{path};
}
PERLEOF
